    background: linear-gradient(135deg, #1a1a2e 0%, #0f3460 100%);
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 20px;
    color: #e0e0e0;
}

.container {
    width: 100%;
    max-width: 500px;
}

.form-wrapper {
    background: #16213e;
    border-radius: 12px;
    padding: 40px;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
    border: 1px solid #0f3460;
}

h1 {
    font-size: 28px;
    font-weight: 600;
    margin-bottom: 12px;
    color: #ffffff;
    text-align: center;
}

.form-description {
    text-align: center;
    color: #b0b0b0;
    margin-bottom: 32px;
    font-size: 14px;
    line-height: 1.5;
}

.contact-form {
    display: flex;
    flex-direction: column;
    gap: 24px;
}

.form-field {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.form-field label {
    font-size: 14px;
    font-weight: 600;
    color: #e0e0e0;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.optional {
    font-size: 12px;
    font-weight: 400;
    color: #888;
    text-transform: none;
    letter-spacing: normal;
}

.form-field input {
    padding: 12px 14px;
    background: #0f3460;
    border: 2px solid #1a5f7a;
    border-radius: 6px;
    color: #e0e0e0;
    font-size: 14px;
    transition: all 0.3s ease;
    outline: none;
}

.form-field input::placeholder {
    color: #666;
}

.form-field input:focus {
    border-color: #00b4d8;
    background: #153a5f;
    box-shadow: 0 0 0 3px rgba(0, 180, 216, 0.1);
}

.form-field input.error {
    border-color: #e74c3c;
    background: rgba(231, 76, 60, 0.05);
}

.form-field input.error:focus {
    box-shadow: 0 0 0 3px rgba(231, 76, 60, 0.1);
}

.form-field input.success {
    border-color: #2ecc71;
    background: rgba(46, 204, 113, 0.05);
}

.form-field input.success:focus {
    box-shadow: 0 0 0 3px rgba(46, 204, 113, 0.1);
}

.helper-text {
    font-size: 12px;
    color: #888;
    line-height: 1.4;
    margin-top: 4px;
}

.error-message {
    font-size: 12px;
    color: #e74c3c;
    min-height: 16px;
    display: block;
}

.submit-button {
    padding: 14px 24px;
    background: linear-gradient(135deg, #00b4d8 0%, #0096c7 100%);
    color: #ffffff;
    border: none;
    border-radius: 6px;
    font-size: 16px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s ease;
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-top: 8px;
}

.submit-button:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 16px rgba(0, 180, 216, 0.3);
}

.submit-button:active {
    transform: translateY(0);
}

.submit-button:disabled {
    opacity: 0.6;
    cursor: not-allowed;
    transform: none;
}

.success-message {
    margin-top: 24px;
    padding: 16px;
    background: rgba(46, 204, 113, 0.1);
    border: 2px solid #2ecc71;
    border-radius: 6px;
    color: #2ecc71;
    text-align: center;
    font-size: 14px;
    animation: slideIn 0.3s ease;
}

.success-message p {
    margin: 0;
}

@keyframes slideIn {
    from {
        opacity: 0;
        transform: translateY(-10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@media (max-width: 480px) {
    .form-wrapper {
        padding: 24px;
    }

    h1 {
        font-size: 24px;
    }

    .contact-form {
        gap: 20px;
    }
}
