+class ContactForm {
+    constructor() {
+        this.form = document.getElementById('contactForm');
+        this.fields = {
+            fullName: document.getElementById('fullName'),
+            email: document.getElementById('email'),
+            phone: document.getElementById('phone')
+        };
+        this.submitButton = this.form.querySelector('.submit-button');
+        this.successMessage = document.getElementById('successMessage');
+        this.init();
+    }
+
+    init() {
+        this.form.addEventListener('submit', (e) => this.handleSubmit(e));
+        
+        Object.entries(this.fields).forEach(([name, field]) => {
+            field.addEventListener('blur', () => this.validateField(name));
+            field.addEventListener('input', () => this.clearError(name));
+        });
+    }
+
+    validateField(fieldName) {
+        const field = this.fields[fieldName];
+        const value = field.value.trim();
+
+        if (fieldName === 'fullName') {
+            if (!value) {
+                this.setError(fieldName, 'Full name is required');
+                return false;
+            }
+            if (value.length < 2) {
+                this.setError(fieldName, 'Full name must be at least 2 characters');
+                return false;
+            }
+            this.setSuccess(fieldName);
+            return true;
+        }
+
+        if (fieldName === 'email') {
+            if (!value) {
+                this.setError(fieldName, 'Email address is required');
+                return false;
+            }
+            if (!this.isValidEmail(value)) {
+                this.setError(fieldName, 'Please enter a valid email address');
+                return false;
+            }
+            this.setSuccess(fieldName);
+            return true;
+        }
+
+        if (fieldName === 'phone') {
+            if (value && !this.isValidPhone(value)) {
+                this.setError(fieldName, 'Please enter a valid phone number');
+                return false;
+            }
+            if (value) {
+                this.setSuccess(fieldName);
+            } else {
+                this.clearError(fieldName);
+            }
+            return true;
+        }
+    }
+
+    isValidEmail(email) {
+        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+        return emailRegex.test(email);
+    }
+
+    isValidPhone(phone) {
+        const phoneRegex = /^[\d\s\-()]+$/;
+        if (!phoneRegex.test(phone)) return false;
+        const digitsOnly = phone.replace(/\D/g, '');
+        return digitsOnly.length >= 10 && digitsOnly.length <= 15;
+    }
+
+    setError(fieldName, message) {
+        const field = this.fields[fieldName];
+        const errorElement = this.form.querySelector(`[data-field="${fieldName}"]`);
+        
+        field.classList.remove('success');
+        field.classList.add('error');
+        errorElement.textContent = message;
+    }
+
+    setSuccess(fieldName) {
+        const field = this.fields[fieldName];
+        const errorElement = this.form.querySelector(`[data-field="${fieldName}"]`);
+        
+        field.classList.remove('error');
+        field.classList.add('success');
+        errorElement.textContent = '';
+    }
+
+    clearError(fieldName) {
+        const field = this.fields[fieldName];
+        const errorElement = this.form.querySelector(`[data-field="${fieldName}"]`);
+        
+        field.classList.remove('error', 'success');
+        errorElement.textContent = '';
+    }
+
+    validateForm() {
+        const isFullNameValid = this.validateField('fullName');
+        const isEmailValid = this.validateField('email');
+        const isPhoneValid = this.validateField('phone');
+        
+        return isFullNameValid && isEmailValid && isPhoneValid;
+    }
+
+    handleSubmit(e) {
+        e.preventDefault();
+        
+        if (this.validateForm()) {
+            this.successMessage.style.display = 'block';
+            this.form.style.display = 'none';
+            
+            setTimeout(() => {
+                this.form.reset();
+                this.form.style.display = 'flex';
+                this.successMessage.style.display = 'none';
+                Object.values(this.fields).forEach(field => {
+                    field.classList.remove('success', 'error');
+                });
